#include <bits/stdc++.h>
using namespace std;
//#define long long ll;

void solve(){
    int n;
    cin>>n;
    
    int total = 3*n;
    
    
    vector<int> a(total+1);
    for(int i=1;i<=total;i++){
        cin>>a[i];
    }
    
     sort(a.begin()+1,a.end(),greater<long long>());
    
   vector<long long> S(total+1,0);
    for(int i=1;i<=total;i++){
        S[i]=S[i-1]+a[i];
    }
    
    long long ans=0;
    
    
    for(int k =0;k<=n;k++){
        int low = 0;
        int high = k-1;
        
        int ox= 0 ;
        
        while(low<=high){
            int mid = low+(high-low)/2;
            long long diff = 2LL*a[mid+1]-a[2*k-mid]-3LL*a[3*n-k-mid];
            
            if(diff>=0){
                ox=mid+1;
                low=mid+1;
            }
            else {
                high =mid-1;
            }
        }
        
        long long val = 2LL*S[ox]+S[2*k-ox]+3LL*S[3*n-k-ox];
         ans=max(ans,val);
        
        
       
    
    
    
    
    }
    cout<<ans<<"\n";
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
	// your code goes here
    int t = 0;
    cin>>t;
    
    while(t--){
        solve();
    }
}
